// `roster run <repo> --budget <usd>`: the coordinator agent on DeepSeek, over the tool backend
// (DESIGN.md §"Coordinator tools"). One WORKFLOW span per run; the coordinator adds AGENT and TOOL spans.
import { join, resolve } from "node:path";
import type { Command } from "../cli.ts";
import { deepseekClient } from "../llm/client.ts";
import { flushObs, initObs, setSession, withSpan } from "../obs/index.ts";
import { repoLabel, reviewSlug } from "../review/export.ts";
import { DEFAULT_DB, newRunId, runCoordinator } from "../agent/coordinator.ts";
import { defaultBackend } from "../agent/tools.ts";
import { DEFAULT_CACHE, UsageError } from "./review.ts";

const USAGE = `usage: roster run <repo> --budget <usd> [--out <dir>] [--run-id <id>] [--db <path>] [--model <m>] [--cache <dir>]

  <repo>           a git URL or local path with Entire checkpoints
  --budget <usd>   hard stop for LLM plus replay cost (required)
  --out <dir>      where plan.json and decisions.json go (default reports/<slug>)
  --run-id <id>    resume this run from ${DEFAULT_DB}, or start it under this id
  --db <path>      state database (default ${DEFAULT_DB})
  --model <m>      coordinator model (default env ROSTER_LLM_MODEL, else deepseek-flash)
  --cache <dir>    fetch cache (default ${DEFAULT_CACHE})

Roster's own model calls go to DeepSeek; set DEEPSEEK_API_KEY in .env.`;

export interface RunArgs {
  repo: string;
  budgetUsd: number;
  out: string | undefined;
  runId: string | undefined;
  db: string;
  model: string | undefined;
  cache: string;
}

/** Parses the arguments after `run`. Throws UsageError on anything it does not accept. */
export function parseRunArgs(args: string[]): RunArgs {
  let repo: string | undefined;
  let budget: string | undefined;
  const parsed: Omit<RunArgs, "repo" | "budgetUsd"> = {
    out: undefined,
    runId: undefined,
    db: DEFAULT_DB,
    model: undefined,
    cache: DEFAULT_CACHE,
  };
  for (let i = 0; i < args.length; i++) {
    const a = args[i]!;
    const eq = a.indexOf("=");
    const name = eq === -1 ? a : a.slice(0, eq);
    const takeValue = (): string => {
      if (eq !== -1) return a.slice(eq + 1);
      const v = args[++i];
      if (v === undefined || v.startsWith("--")) throw new UsageError(`${name} needs a value`);
      return v;
    };
    if (name === "--budget") budget = takeValue();
    else if (name === "--out") parsed.out = takeValue();
    else if (name === "--run-id") parsed.runId = takeValue();
    else if (name === "--db") parsed.db = takeValue();
    else if (name === "--model") parsed.model = takeValue();
    else if (name === "--cache") parsed.cache = takeValue();
    else if (a.startsWith("-")) throw new UsageError(`unknown flag ${a}`);
    else if (repo === undefined) repo = a;
    else throw new UsageError(`unexpected argument ${a}`);
  }
  if (repo === undefined) throw new UsageError("missing <repo>");
  if (budget === undefined) throw new UsageError("--budget is required");
  const budgetUsd = Number(budget);
  if (!Number.isFinite(budgetUsd) || budgetUsd <= 0) throw new UsageError(`--budget must be a positive number, got ${budget}`);
  return { repo, budgetUsd, ...parsed };
}

/** Runs the coordinator. Exit 0 when it promoted or honestly found no better setup, 1 otherwise. */
export async function runRun(args: RunArgs): Promise<number> {
  const label = repoLabel(args.repo);
  const outDir = resolve(args.out ?? join("reports", reviewSlug(args.repo)));
  const llm = deepseekClient({ model: args.model });
  const runId = args.runId ?? newRunId(new Date());
  await initObs({ workflowName: "roster-run" });
  setSession(runId);
  try {
    const res = await withSpan("WORKFLOW", "review", { repo: label }, () =>
      runCoordinator({
        repo: args.repo,
        budgetUsd: args.budgetUsd,
        llm,
        backend: defaultBackend({ cacheDir: args.cache, replay: { repo: args.repo } }),
        outDir,
        dbPath: resolve(args.db),
        runId,
        model: args.model,
      }),
    );
    console.log(`roster run ${label} (${res.runId}${res.resumed ? ", resumed" : ""}): ${res.outcome}`);
    console.log(res.summary);
    console.log(
      `spent $${res.spentUsd.toFixed(4)} of $${args.budgetUsd} (LLM $${res.llmUsd.toFixed(4)}, replays $${res.replayUsd.toFixed(4)}) in ${res.turns} turns`,
    );
    if (res.unpricedLlmCalls > 0) {
      console.warn(`warning: ${res.unpricedLlmCalls} LLM calls have no price in src/price; their cost is not in the total`);
    }
    console.log(`wrote ${[res.planPath, res.decisionsPath].filter(Boolean).join(", ")}`);
    return res.outcome === "promoted" || res.outcome === "no_better_setup" ? 0 : 1;
  } finally {
    await flushObs();
  }
}

export const runCommand: Command = {
  name: "run",
  summary: "run the coordinator agent: plan, replay, gate (needs DEEPSEEK_API_KEY)",
  usage: USAGE,
  async run(args) {
    let parsed: RunArgs;
    try {
      parsed = parseRunArgs(args);
    } catch (err) {
      if (!(err instanceof UsageError)) throw err;
      console.error(`roster run: ${err.message}\n\n${USAGE}`);
      return 2;
    }
    return runRun(parsed);
  },
};

if (import.meta.main) {
  process.exitCode = await runCommand.run(process.argv.slice(2));
}
// Roster's own model calls, on DeepSeek's OpenAI-compatible API. Never a Claude API
// (DESIGN.md §"Models Roster itself uses"). Retries 429/5xx twice with backoff (§"Recovery").
import OpenAI from "openai";
import { traceOpenAI, withSpan } from "../obs/index.ts";
import { priceSession } from "../price/index.ts";
import {
  type ChatMessage,
  type ChatRequest,
  type ChatResult,
  type ChatUsage,
  DEEPSEEK_BASE_URL,
  DEFAULT_MODEL,
  type LlmClient,
  type ToolCall,
} from "./types.ts";

export * from "./types.ts";

/** The slice of an OpenAI-style chat completion response the client reads. */
export interface RawCompletion {
  model: string;
  choices: {
    message: {
      content: string | null;
      tool_calls?: (
        | { id: string; type: "function"; function: { name: string; arguments: string } }
        | { id: string; type: "custom"; custom: { name: string; input: string } }
      )[];
    };
  }[];
  usage?: {
    prompt_tokens: number;
    completion_tokens: number;
    prompt_tokens_details?: { cached_tokens?: number } | null;
    /** DeepSeek's own cache counter. */
    prompt_cache_hit_tokens?: number;
  };
}

/** Sends one chat completion request. The default goes through the `openai` package. */
export type Transport = (body: Record<string, unknown>) => Promise<RawCompletion>;

export interface DeepSeekOptions {
  /** Default: env DEEPSEEK_API_KEY. */
  apiKey?: string;
  baseURL?: string;
  /** Default: env ROSTER_LLM_MODEL, else DEFAULT_MODEL. */
  model?: string;
  /** Retries on 429/5xx only. Default 2. */
  maxRetries?: number;
  /** First backoff delay; doubles per retry. Default 1000. */
  retryBaseMs?: number;
  sleep?: (ms: number) => Promise<void>;
  /** Replaces the network call. Tests use it; production leaves it unset. */
  transport?: Transport;
}

/** The model a call uses when the request names none. */
export function defaultModel(): string {
  return process.env.ROSTER_LLM_MODEL || DEFAULT_MODEL;
}

/** HTTP status carried by an SDK or fetch error, else null. */
export function errorStatus(err: unknown): number | null {
  if (typeof err === "object" && err !== null && "status" in err) {
    const s = (err as { status: unknown }).status;
    if (typeof s === "number") return s;
  }
  return null;
}

/** True for the failures worth retrying: rate limits and server errors. */
export function isRetryable(err: unknown): boolean {
  const s = errorStatus(err);
  return s !== null && (s === 429 || s >= 500);
}

function toWire(m: ChatMessage): Record<string, unknown> {
  if (m.role !== "assistant" || !m.tool_calls?.length) return { ...m };
  return {
    role: "assistant",
    content: m.content,
    tool_calls: m.tool_calls.map((c) => ({ id: c.id, type: "function", function: { name: c.name, arguments: c.arguments } })),
  };
}

/** Maps a raw completion to a ChatResult, priced for its model via src/price. */
export function toResult(raw: RawCompletion): ChatResult {
  const msg = raw.choices[0]?.message ?? { content: null };
  const toolCalls: ToolCall[] = (msg.tool_calls ?? []).map((c) =>
    c.type === "function"
      ? { id: c.id, name: c.function.name, arguments: c.function.arguments }
      : { id: c.id, name: c.custom.name, arguments: c.custom.input },
  );
  const u = raw.usage;
  const cached = u?.prompt_cache_hit_tokens ?? u?.prompt_tokens_details?.cached_tokens ?? 0;
  const usage: ChatUsage = {
    promptTokens: u?.prompt_tokens ?? 0,
    cachedPromptTokens: cached,
    completionTokens: u?.completion_tokens ?? 0,
  };
  const costUsd = u
    ? priceSession(raw.model, {
        input: usage.promptTokens - cached,
        output: usage.completionTokens,
        cache_read: cached,
        prompt_tokens: usage.promptTokens,
      }).usd
    : null;
  return {
    message: { role: "assistant", content: msg.content, ...(toolCalls.length ? { tool_calls: toolCalls } : {}) },
    toolCalls,
    usage,
    costUsd,
    model: raw.model,
  };
}

/** A client for DeepSeek's chat completions. Throws when no API key is configured and no transport is given. */
export function deepseekClient(opts: DeepSeekOptions = {}): LlmClient {
  const maxRetries = opts.maxRetries ?? 2;
  const baseMs = opts.retryBaseMs ?? 1000;
  const sleep = opts.sleep ?? ((ms: number) => Bun.sleep(ms));
  let transport = opts.transport;
  if (!transport) {
    const apiKey = opts.apiKey ?? process.env.DEEPSEEK_API_KEY;
    if (!apiKey) throw new Error("DEEPSEEK_API_KEY is not set; Roster's own model calls go to DeepSeek");
    // The SDK's own retries are off: ours are numbered and traced.
    const sdk = new OpenAI({ apiKey, baseURL: opts.baseURL ?? DEEPSEEK_BASE_URL, maxRetries: 0 });
    // Wrapped per call: the CLI builds this client before initObs runs, and traceOpenAI is a no-op until tracing is on.
    transport = (body) => traceOpenAI(sdk).chat.completions.create(body as never) as Promise<RawCompletion>;
  }
  const send = transport;

  return {
    async chat(req: ChatRequest): Promise<ChatResult> {
      const body: Record<string, unknown> = {
        model: req.model ?? opts.model ?? defaultModel(),
        messages: req.messages.map(toWire),
      };
      if (req.temperature !== undefined) body.temperature = req.temperature;
      if (req.tools?.length) {
        body.tools = req.tools.map((t) => ({
          type: "function",
          function: { name: t.name, description: t.description, parameters: t.parameters },
        }));
      }
      for (let attempt = 1; ; attempt++) {
        try {
          if (attempt === 1) return toResult(await send(body));
          // Retries are a recovery path, so each one is a TOOL span carrying roster.attempt.
          return await withSpan("TOOL", "llm retry", { attempt }, async () => toResult(await send(body)));
        } catch (err) {
          if (!isRetryable(err) || attempt > maxRetries) throw err;
          await sleep(baseMs * 2 ** (attempt - 1));
        }
      }
    },
  };
}

/** One scripted reply: a partial result, a function of the request, or an error to throw. */
export type FakeStep =
  | { content?: string | null; toolCalls?: ToolCall[]; costUsd?: number | null; usage?: Partial<ChatUsage>; model?: string }
  | ((req: ChatRequest) => FakeStep)
  | Error;

export interface FakeClient extends LlmClient {
  /** Every request received, in order. */
  requests: ChatRequest[];
}

/** A scripted client for tests. Each chat() consumes one step; running out throws. */
export function fakeClient(steps: FakeStep[]): FakeClient {
  const queue = [...steps];
  const requests: ChatRequest[] = [];
  return {
    requests,
    async chat(req) {
      requests.push(structuredClone(req));
      let step = queue.shift();
      if (step === undefined) throw new Error("fake LLM client: script exhausted");
      while (typeof step === "function") step = step(req);
      if (step instanceof Error) throw step;
      const toolCalls = step.toolCalls ?? [];
      return {
        message: { role: "assistant", content: step.content ?? null, ...(toolCalls.length ? { tool_calls: toolCalls } : {}) },
        toolCalls,
        usage: { promptTokens: 0, cachedPromptTokens: 0, completionTokens: 0, ...step.usage },
        costUsd: step.costUsd === undefined ? 0 : step.costUsd,
        model: step.model ?? req.model ?? "fake",
      };
    },
  };
}

let fakeIds = 0;
/** A tool call for a fake script. Pass a string to script malformed JSON arguments. */
export function fakeToolCall(name: string, args: Record<string, unknown> | string = {}): ToolCall {
  return { id: `call_${++fakeIds}`, name, arguments: typeof args === "string" ? args : JSON.stringify(args) };
}
// neatlogs instrumentation of Roster's own runs (DESIGN.md §"Observability (neatlogs)").
// One review = one trace: WORKFLOW root → AGENT coordinator → TOOL steps and attempts, plus a GUARDRAIL gate.
// Without NEATLOGS_API_KEY every call is a no-op and the wrapped work still runs.
import type { TraceOptions } from "neatlogs";
import { EvidenceLevel, FailureCode } from "../types.ts";
import { type SpanAttrs, type SpanKind, toAttributes } from "./attributes.ts";

export type { SpanAttrs, SpanKind } from "./attributes.ts";

/** What the SDK hands a span body. `traceId` is the OpenTelemetry trace id, when the span has one. */
export interface ObsSpan {
  setAttribute(key: string, value: string | number | boolean): void;
  traceId?: string;
}

/** The neatlogs SDK as its own type definitions declare it (`neatlogs` and `neatlogs/openai`). */
type NeatlogsModule = typeof import("neatlogs");
type WrapOpenAI = typeof import("neatlogs/openai").wrapOpenAI;
/** The OpenTelemetry span that trace()'s body receives. `neatlogs` also exports a `Span` decorator, so derive it. */
type NeatlogsSpan = Parameters<NeatlogsModule["trace"]>[1] extends (span: infer S) => unknown ? S : never;

const NOOP_SPAN: ObsSpan = { setAttribute() {} };

let sdk: NeatlogsModule | null = null;
let wrapOpenAI: WrapOpenAI | null = null;
let sessionId: string | undefined;
let warned = false;

function warnOnce(msg: string): void {
  if (warned) return;
  warned = true;
  console.warn(`[roster] observability disabled: ${msg}`);
}

/**
 * Starts neatlogs for this process. Resolves to true when tracing is live.
 * With NEATLOGS_API_KEY unset (or the SDK not installed) it resolves to false and warns once.
 */
export async function initObs(opts: { workflowName: string }): Promise<boolean> {
  const apiKey = process.env.NEATLOGS_API_KEY;
  if (!apiKey) {
    warnOnce("NEATLOGS_API_KEY is not set");
    return false;
  }
  try {
    const mod = await import("neatlogs");
    await mod.init({ apiKey, workflowName: opts.workflowName });
    wrapOpenAI = (await import("neatlogs/openai")).wrapOpenAI;
    sdk = mod;
    return true;
  } catch (err) {
    warnOnce(`could not start neatlogs (${err instanceof Error ? err.message : String(err)})`);
    return false;
  }
}

/**
 * Wraps an OpenAI-compatible client so each of its calls becomes an LLM span. Returns the client unchanged
 * while tracing is off, so callers may wrap at call time (the CLI builds clients before initObs runs).
 */
export function traceOpenAI<T extends object>(client: T): T {
  return sdk && wrapOpenAI ? wrapOpenAI(client) : client;
}

/** True once initObs has enabled tracing. */
export function obsEnabled(): boolean {
  return sdk !== null;
}

/** Tags the current review. Every span opened after this carries it as `session.id`. */
export function setSession(reviewId: string): void {
  sessionId = reviewId;
}

/**
 * Runs `fn` inside one span of the given kind. The span is nested under whatever span is active,
 * so calling withSpan inside a WORKFLOW body builds the tree. Errors propagate after the span closes.
 */
export async function withSpan<T>(
  kind: SpanKind,
  name: string,
  attrs: SpanAttrs,
  fn: (span: ObsSpan) => Promise<T>,
): Promise<T> {
  if (!sdk) return fn(NOOP_SPAN);
  const client = sdk;
  // The SDK groups a review's traces by session on the WORKFLOW root; every span also carries it as an attribute.
  const options: TraceOptions = { name, kind };
  if (kind === "WORKFLOW" && sessionId !== undefined) options.sessionId = sessionId;
  return client.trace(options, async (span) => {
    for (const [key, value] of Object.entries(toAttributes(attrs))) span.setAttribute(key, value);
    if (sessionId !== undefined) span.setAttribute("session.id", sessionId);
    return fn(toObsSpan(span));
  });
}

/** Adapts an SDK span (an OpenTelemetry span) to ObsSpan. The trace id comes from spanContext(). */
function toObsSpan(span: NeatlogsSpan): ObsSpan {
  // A bare `traceId` field is honored too, for span stand-ins that carry one directly.
  const direct = (span as { traceId?: string }).traceId;
  return {
    setAttribute: (key, value) => void span.setAttribute(key, value),
    traceId: direct ?? span.spanContext?.().traceId,
  };
}

/** Outcome of one replay attempt, recorded as a finished TOOL span. */
export interface AttemptOutcome {
  failureCode?: FailureCode | FailureCode[];
  evidenceLevel?: EvidenceLevel;
  costUsd?: number;
}

/** Records one replay attempt as a TOOL span carrying its outcome. The span has no body work of its own. */
export async function recordAttempt(spanAttrs: SpanAttrs, attempt: number, outcome: AttemptOutcome): Promise<void> {
  await withSpan("TOOL", `replay attempt ${attempt}`, { ...spanAttrs, ...outcome, attempt }, async () => undefined);
}

/** Sends buffered spans. Call once before the process exits. A no-op when tracing is off. */
export async function flushObs(): Promise<void> {
  if (sdk) await sdk.flush();
}
// DeepSeek time-of-day pricing (DESIGN.md §"Candidate generation").
// Source: https://api-docs.deepseek.com/quick_start/pricing
//
// Peak is 01:00–04:00 and 06:00–10:00 UTC, Monday through Friday. Every other hour is off-peak, weekends
// included. Off-peak is half the peak rate. The rows hold the PEAK rates:
//   input = cache miss, cache_read = cache hit, output = output.
// The page also excludes Chinese public holidays from peak. We keep no holiday calendar, so a holiday is
// priced at peak. That overstates its cost and never understates it.
//
// These rows live here, not in src/price/prices.json. priceSession() reads prices.json with no time-of-day
// rule, so a DeepSeek row there would bill off-peak runs at the peak rate.

import type { TokenCounts } from "./index.ts";

export const OFF_PEAK_FACTOR = 0.5;

export interface DeepSeekRow {
  id: string;
  model_pattern: string;
  /** Peak USD per 1M tokens. */
  input: number;
  output: number;
  cache_read: number;
  cache_write: null;
  source_url: string;
  checked_on: string;
}

const SOURCE_URL = "https://api-docs.deepseek.com/quick_start/pricing";
const CHECKED_ON = "2026-10-10";

export const DEEPSEEK_ROWS: DeepSeekRow[] = [
  {
    id: "deepseek-flash",
    model_pattern: "deepseek-flash",
    input: 0.3,
    output: 1.2,
    cache_read: 0.006,
    cache_write: null,
    source_url: SOURCE_URL,
    checked_on: CHECKED_ON,
  },
  {
    id: "deepseek-v4-pro",
    model_pattern: "deepseek-v4-pro",
    input: 1.32,
    output: 3.96,
    cache_read: 0.044,
    cache_write: null,
    source_url: SOURCE_URL,
    checked_on: CHECKED_ON,
  },
];

export type DeepSeekPrice = {
  /** null when a counted token type has no confirmed price. */
  usd: number | null;
  row_id: string;
  peak: boolean;
};

/** True during DeepSeek's peak window, judged in UTC. The end hour is exclusive: 04:00 and 10:00 are off-peak. */
export function isPeak(at: Date): boolean {
  const day = at.getUTCDay();
  if (day === 0 || day === 6) return false;
  const h = at.getUTCHours();
  return (h >= 1 && h < 4) || (h >= 6 && h < 10);
}

/**
 * Prices one token-count record for a DeepSeek model at a given instant.
 * Returns null for a model that is not a DeepSeek row. Returns usd: null when a counted token type has no price.
 */
export function priceDeepSeek(model: string, tokens: TokenCounts, at: Date): DeepSeekPrice | null {
  const row = DEEPSEEK_ROWS.find((r) => r.model_pattern === model.trim().toLowerCase());
  if (row === undefined) return null;

  const peak = isPeak(at);
  const factor = peak ? 1 : OFF_PEAK_FACTOR;
  const counts: [number, number | null | undefined][] = [
    [tokens.input, row.input],
    [tokens.output, row.output],
    [tokens.cache_read ?? 0, row.cache_read],
    [tokens.cache_write ?? 0, row.cache_write],
  ];
  let usd = 0;
  for (const [count, price] of counts) {
    if (count === 0) continue;
    if (price === null || price === undefined) return { usd: null, row_id: row.id, peak };
    usd += (count * price) / 1_000_000;
  }
  return { usd: usd * factor, row_id: row.id, peak };
}
